/* =====================================================================
   app1_4_gold_stub.sql   APP-1 stage 4: synthetic gold stub and merge stub
   GENERATED by tools/bundle_sql.py from the files listed below. Do not edit:
   change the source file and run `python tools/bundle_sql.py` again.
   Paste the whole file into New query of the ATLAS_SQL_DB item (type SQL database),
   run it once, and copy the Messages tab. Each file runs in its own batch.
   Files, in run order:
     db/dev/gold_stub.sql
     db/dev/merge_stub.sql
   ===================================================================== */
SET NOCOUNT ON;
PRINT N'=== app1_4_gold_stub: 2 file(s) ===';

PRINT N'--- db/dev/gold_stub.sql';
EXEC (N'/* =====================================================================
   gold_stub.sql             APP-1, synthetic stand-in for the gold layer
   Database : the ATLAS Fabric SQL database (item of type SQL database)
   Run      : Fabric portal > SQL database > New query > paste > Run
   Re-runnable: yes. Tables are created only if missing, rows are loaded only
   when the stub tables are empty, views are created only if no object of that
   name exists (the data engineer''s real views are never overwritten).

   Why: the app (APP-2 onwards) and the rules need the gold contract views
   (01_Architecture_and_Contracts.md section 6.1) before the data engineer
   delivers the real ones (Wed 18 Nov). This script builds them over small
   SYNTHETIC tables in schema dev. When the real gold lands, run
   db/dev/drop_stub.sql: it removes only objects that carry the marker
   "ATLAS-STUB" in their definition.

   ALL DATA HERE IS INVENTED. Identifiers start with SYN-; manufacturers are
   "SYNTHETIC MFR A/B/C". Nothing comes from the client.

   Created (tables, schema dev): stub_floc, stub_equipment, stub_defect.
   Created (views, schema gold, only if absent):
     gold.vw_equipment_current, gold.vw_equipment_field_current,
     gold.vw_floc_current, gold.vw_verification_score,
     gold.vw_verification_by_business_unit.
   No gold table is created (gold.equipment, gold.functional_location,
   gold.class_characteristic ... belong to the data engineer).

   DATA PLAN
   ---------
   30 hand-planned heaters: equipment SYN-EQ-0001 .. SYN-EQ-0030, three in each
   of the ten profit centres (1-3 ROCKIES-DJ BASIN, 4-6 ROCKIES-PRB,
   7-9 ROCKIES-OTHER, 10-12 OP RES DB TX, 13-15 OP RES DB NM, 16-18 OP RES MB,
   19-21 OP RES MB CROWNROCK, 22-24 OP EOR, 25-27 OP EOR GAS PLANT,
   28-30 OP EOR CO2 OPS). equipment_id 1..30 follow that order.
   Plus 2,500 CLEAN filler heaters SYN-EQ-1001 .. SYN-EQ-3500 (fired, duty
   present, tag present, unique serial, consistent classes, spread over the ten
   profit centres) for the paging test. equipment_id 31 .. 2530.

   Deliberate defects (exactly these; also stored in dev.stub_defect so tests
   can assert counts without hard-coding numbers):
     UNFIRED_TREATER    4 rows: SYN-EQ-0002, 0008, 0014, 0023
                        (floc_class VESSEL_HEATER_TRTR, fired_unfired UNFIRED)
     MISSING_HEAT_DUTY  4 rows: SYN-EQ-0003, 0011, 0019, 0026
                        (heat_duty_mmbtu_hr NULL, heat_duty_source MISSING)
     DUPLICATE_SERIAL   4 rows in 2 pairs: SYN-EQ-0006 + 0015 share
                        SYN-SN-DUP-A; SYN-EQ-0009 + 0029 share SYN-SN-DUP-B
                        (same manufacturer inside each pair)
     MISSING_TAG        4 rows: SYN-EQ-0007, 0016, 0021, 0030
                        (equipment_tag_number NULL)
     CLASS_MISMATCH     4 rows: SYN-EQ-0001 (floc HEATER, equip VESSEL),
                        SYN-EQ-0010 (class type BOILER on a HEATER),
                        SYN-EQ-0018 (floc treater, equip HEATER),
                        SYN-EQ-0025 (floc BOILER, equip HEATER)
   No row has two defects. 20 defective rows, 10 clean hand-planned rows
   (0004, 0005, 0012, 0013, 0017, 0020, 0022, 0024, 0027, 0028).
   Consistent class triples (floc_class / equip_class / class_type):
     heater  HEATER / HEATER / HEATER
     treater VESSEL_HEATER_TRTR / VESSEL / HEATER TREATER

   Verification marks (key_fields_verified of 5, used only by the two
   verification views): 0004=5, 0005=3, 0012=5, 0013=2, 0020=5, 0022=1,
   0027=4; fillers: every 10th = 5, every 7th (not 10th) = 3, others 0.
   Formula (working assumption for Q-454): verification_pct =
   key_fields_verified / key_fields_total * 100, key_fields_total = 5.
   ===================================================================== */
SET NOCOUNT ON;

IF CAST(SERVERPROPERTY(''EngineEdition'') AS int) = 11
   OR @@VERSION LIKE N''%Data Warehouse%''
   OR DB_NAME() NOT LIKE N''ATLAS[_]SQL[_]DB%''
BEGIN
    PRINT ''FAIL STUB.0 wrong editor: connected to "'' + DB_NAME() + ''" on engine '' + ISNULL(CAST(SERVERPROPERTY(''EngineEdition'') AS varchar(20)), ''?'') + '' (11 = the warehouse-style engine, which the SQL analytics endpoint uses). Open the item named ATLAS_SQL_DB whose type is SQL database and run this from New query there. Nothing was changed.'';
    RETURN;
END
PRINT ''OK  connected to database "'' + DB_NAME() + ''"'';

DECLARE @steps int = 0, @failed int = 0, @n int;

/* working tables, only used while loading */
DECLARE @pc TABLE (idx tinyint NOT NULL PRIMARY KEY, name nvarchar(40) NOT NULL);
DECLARE @stage TABLE
(
    seq        int           NOT NULL PRIMARY KEY,   -- load order = equipment_id order
    code       nvarchar(10)  NOT NULL,               -- 0001 .. 0030, 1001 .. 3500
    pc         tinyint       NOT NULL,               -- 1..10 (see @pc)
    floc_class nvarchar(30)  NOT NULL,
    equip_class nvarchar(30) NOT NULL,
    class_type nvarchar(30)  NOT NULL,
    fired      nvarchar(30)  NOT NULL,
    duty       decimal(18,4) NULL,
    tag        nvarchar(30)  NULL,
    serial     nvarchar(30)  NOT NULL,
    mfr        nvarchar(30)  NOT NULL,
    verified   int           NOT NULL
);
DECLARE @k TABLE (k int NOT NULL PRIMARY KEY);

/* ---- STUB.1 schemas ------------------------------------------------------ */
BEGIN TRY
    IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = N''gold'')
        EXEC (N''CREATE SCHEMA gold AUTHORIZATION dbo'');
    IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = N''dev'')
        EXEC (N''CREATE SCHEMA dev AUTHORIZATION dbo'');
    SET @steps += 1;
    PRINT ''OK  STUB.1 schemas gold and dev ready'';
END TRY
BEGIN CATCH
    SET @steps += 1; SET @failed += 1;
    PRINT ''FAIL STUB.1 CREATE SCHEMA ... AUTHORIZATION dbo, error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
    PRINT ''gold_stub RESULT: '' + CAST(@failed AS varchar(12)) + '' CHECK(S) FAILED'';
    RETURN;
END CATCH;

/* ---- STUB.2 stub tables (schema dev, names start with stub_) ------------- */
BEGIN TRY
    IF OBJECT_ID(N''dev.stub_floc'', N''U'') IS NULL
        EXEC (N''CREATE TABLE dev.stub_floc
        (
            functional_location          nvarchar(40) NOT NULL CONSTRAINT pk_stub_floc PRIMARY KEY,
            floc_description             nvarchar(40) NOT NULL,
            superior_functional_location nvarchar(40) NULL,
            floc_class                   nvarchar(30) NOT NULL,
            tech_object_type             nvarchar(30) NULL,
            floc_user_status             nvarchar(30) NOT NULL,
            profit_center_name           nvarchar(40) NOT NULL,
            level1_id                    nvarchar(40) NULL,
            level2_id                    nvarchar(40) NULL,
            level3_id                    nvarchar(40) NULL,
            level4_id                    nvarchar(40) NULL,
            level5_id                    nvarchar(40) NULL,
            level6_id                    nvarchar(40) NULL,
            golden_version_id            int          NOT NULL,
            last_changed_at_utc          datetime2(3) NULL
        )'');

    IF OBJECT_ID(N''dev.stub_equipment'', N''U'') IS NULL
        EXEC (N''CREATE TABLE dev.stub_equipment
        (
            equipment_id               int           IDENTITY(1,1) NOT NULL CONSTRAINT pk_stub_equipment PRIMARY KEY,
            equipment_number           nvarchar(18)  NOT NULL CONSTRAINT uq_stub_equipment_number UNIQUE,
            equipment_description      nvarchar(40)  NOT NULL,
            functional_location        nvarchar(40)  NOT NULL CONSTRAINT uq_stub_equipment_floc UNIQUE,
            equipment_tag_number       nvarchar(30)  NULL,
            equip_class                nvarchar(30)  NOT NULL,
            class_type                 nvarchar(30)  NOT NULL,
            object_type                nvarchar(30)  NOT NULL,
            manufacturer               nvarchar(30)  NOT NULL,
            model_number               nvarchar(20)  NOT NULL,
            manufacturer_serial_number nvarchar(30)  NOT NULL,
            fired_unfired              nvarchar(30)  NOT NULL,
            heat_duty_mmbtu_hr         decimal(18,4) NULL,
            heat_duty_source           nvarchar(20)  NOT NULL,
            equipment_user_status      nvarchar(30)  NOT NULL,
            profit_center_name         nvarchar(40)  NOT NULL,
            planner_group              nvarchar(40)  NOT NULL,
            heater_population_method   nvarchar(10)  NOT NULL,
            golden_version_id          int           NOT NULL,
            last_changed_at_utc        datetime2(3)  NULL,
            baseline_as_of_utc         datetime2(3)  NOT NULL,
            key_fields_verified        int           NOT NULL,
            last_verified_at_utc       datetime2(3)  NULL
        )'');

    IF OBJECT_ID(N''dev.stub_defect'', N''U'') IS NULL
        EXEC (N''CREATE TABLE dev.stub_defect
        (
            equipment_number nvarchar(18)  NOT NULL,
            defect_code      nvarchar(30)  NOT NULL,
            note             nvarchar(200) NULL,
            CONSTRAINT pk_stub_defect PRIMARY KEY (equipment_number, defect_code)
        )'');

    SET @steps += 1;
    PRINT ''OK  STUB.2 tables dev.stub_floc, dev.stub_equipment, dev.stub_defect exist'';
END TRY
BEGIN CATCH
    SET @steps += 1; SET @failed += 1;
    PRINT ''FAIL STUB.2 CREATE TABLE, error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
    PRINT ''gold_stub RESULT: '' + CAST(@failed AS varchar(12)) + '' CHECK(S) FAILED'';
    RETURN;
END CATCH;

/* ---- STUB.3 load synthetic rows (only into empty tables, one transaction) -- */
BEGIN TRY
    IF NOT EXISTS (SELECT 1 FROM dev.stub_floc)
       AND NOT EXISTS (SELECT 1 FROM dev.stub_equipment)
       AND NOT EXISTS (SELECT 1 FROM dev.stub_defect)
    BEGIN
        INSERT INTO @pc (idx, name) VALUES
            (1,  N''ROCKIES-DJ BASIN''),
            (2,  N''ROCKIES-PRB''),
            (3,  N''ROCKIES-OTHER''),
            (4,  N''OP RES DB TX''),
            (5,  N''OP RES DB NM''),
            (6,  N''OP RES MB''),
            (7,  N''OP RES MB CROWNROCK''),
            (8,  N''OP EOR''),
            (9,  N''OP EOR GAS PLANT''),
            (10, N''OP EOR CO2 OPS'');

        /* 30 hand-planned heaters (see DATA PLAN above for the defect map) */
        INSERT INTO @stage (seq, code, pc, floc_class, equip_class, class_type, fired, duty, tag, serial, mfr, verified) VALUES
            (1,  N''0001'', 1,  N''HEATER'',            N''VESSEL'', N''HEATER'',         N''FIRED'',   2.5,  N''SYN-TAG-0001'', N''SYN-SN-0001'',    N''SYNTHETIC MFR A'', 0),
            (2,  N''0002'', 1,  N''VESSEL_HEATER_TRTR'', N''VESSEL'', N''HEATER TREATER'', N''UNFIRED'', 4.0,  N''SYN-TAG-0002'', N''SYN-SN-0002'',    N''SYNTHETIC MFR B'', 0),
            (3,  N''0003'', 1,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   NULL, N''SYN-TAG-0003'', N''SYN-SN-0003'',    N''SYNTHETIC MFR C'', 0),
            (4,  N''0004'', 2,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   1.5,  N''SYN-TAG-0004'', N''SYN-SN-0004'',    N''SYNTHETIC MFR A'', 5),
            (5,  N''0005'', 2,  N''VESSEL_HEATER_TRTR'', N''VESSEL'', N''HEATER TREATER'', N''FIRED'',   3.0,  N''SYN-TAG-0005'', N''SYN-SN-0005'',    N''SYNTHETIC MFR B'', 3),
            (6,  N''0006'', 2,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   6.0,  N''SYN-TAG-0006'', N''SYN-SN-DUP-A'',   N''SYNTHETIC MFR C'', 0),
            (7,  N''0007'', 3,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   2.0,  NULL,            N''SYN-SN-0007'',    N''SYNTHETIC MFR A'', 0),
            (8,  N''0008'', 3,  N''VESSEL_HEATER_TRTR'', N''VESSEL'', N''HEATER TREATER'', N''UNFIRED'', 5.0,  N''SYN-TAG-0008'', N''SYN-SN-0008'',    N''SYNTHETIC MFR B'', 0),
            (9,  N''0009'', 3,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   7.5,  N''SYN-TAG-0009'', N''SYN-SN-DUP-B'',   N''SYNTHETIC MFR C'', 0),
            (10, N''0010'', 4,  N''HEATER'',            N''HEATER'', N''BOILER'',         N''FIRED'',   8.0,  N''SYN-TAG-0010'', N''SYN-SN-0010'',    N''SYNTHETIC MFR A'', 0),
            (11, N''0011'', 4,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   NULL, N''SYN-TAG-0011'', N''SYN-SN-0011'',    N''SYNTHETIC MFR B'', 0),
            (12, N''0012'', 4,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   3.5,  N''SYN-TAG-0012'', N''SYN-SN-0012'',    N''SYNTHETIC MFR C'', 5),
            (13, N''0013'', 5,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   1.0,  N''SYN-TAG-0013'', N''SYN-SN-0013'',    N''SYNTHETIC MFR A'', 2),
            (14, N''0014'', 5,  N''VESSEL_HEATER_TRTR'', N''VESSEL'', N''HEATER TREATER'', N''UNFIRED'', 4.5,  N''SYN-TAG-0014'', N''SYN-SN-0014'',    N''SYNTHETIC MFR B'', 0),
            (15, N''0015'', 5,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   6.5,  N''SYN-TAG-0015'', N''SYN-SN-DUP-A'',   N''SYNTHETIC MFR C'', 0),
            (16, N''0016'', 6,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   2.25, NULL,            N''SYN-SN-0016'',    N''SYNTHETIC MFR A'', 0),
            (17, N''0017'', 6,  N''VESSEL_HEATER_TRTR'', N''VESSEL'', N''HEATER TREATER'', N''FIRED'',   3.25, N''SYN-TAG-0017'', N''SYN-SN-0017'',    N''SYNTHETIC MFR B'', 0),
            (18, N''0018'', 6,  N''VESSEL_HEATER_TRTR'', N''HEATER'', N''HEATER TREATER'', N''FIRED'',   5.5,  N''SYN-TAG-0018'', N''SYN-SN-0018'',    N''SYNTHETIC MFR C'', 0),
            (19, N''0019'', 7,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   NULL, N''SYN-TAG-0019'', N''SYN-SN-0019'',    N''SYNTHETIC MFR A'', 0),
            (20, N''0020'', 7,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   4.25, N''SYN-TAG-0020'', N''SYN-SN-0020'',    N''SYNTHETIC MFR B'', 5),
            (21, N''0021'', 7,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   2.75, NULL,            N''SYN-SN-0021'',    N''SYNTHETIC MFR C'', 0),
            (22, N''0022'', 8,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   9.0,  N''SYN-TAG-0022'', N''SYN-SN-0022'',    N''SYNTHETIC MFR A'', 1),
            (23, N''0023'', 8,  N''VESSEL_HEATER_TRTR'', N''VESSEL'', N''HEATER TREATER'', N''UNFIRED'', 3.75, N''SYN-TAG-0023'', N''SYN-SN-0023'',    N''SYNTHETIC MFR B'', 0),
            (24, N''0024'', 8,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   1.75, N''SYN-TAG-0024'', N''SYN-SN-0024'',    N''SYNTHETIC MFR C'', 0),
            (25, N''0025'', 9,  N''BOILER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   10.0, N''SYN-TAG-0025'', N''SYN-SN-0025'',    N''SYNTHETIC MFR A'', 0),
            (26, N''0026'', 9,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   NULL, N''SYN-TAG-0026'', N''SYN-SN-0026'',    N''SYNTHETIC MFR B'', 0),
            (27, N''0027'', 9,  N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   5.25, N''SYN-TAG-0027'', N''SYN-SN-0027'',    N''SYNTHETIC MFR C'', 4),
            (28, N''0028'', 10, N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   2.1,  N''SYN-TAG-0028'', N''SYN-SN-0028'',    N''SYNTHETIC MFR A'', 0),
            (29, N''0029'', 10, N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   6.75, N''SYN-TAG-0029'', N''SYN-SN-DUP-B'',   N''SYNTHETIC MFR C'', 0),
            (30, N''0030'', 10, N''HEATER'',            N''HEATER'', N''HEATER'',         N''FIRED'',   3.9,  NULL,            N''SYN-SN-0030'',    N''SYNTHETIC MFR B'', 0);

        /* 2,500 clean filler heaters: seq 1001 .. 3500 */
        INSERT INTO @k (k)
        SELECT TOP (2500) ROW_NUMBER() OVER (ORDER BY (SELECT NULL))
        FROM sys.all_objects AS a CROSS JOIN sys.all_objects AS b;

        INSERT INTO @stage (seq, code, pc, floc_class, equip_class, class_type, fired, duty, tag, serial, mfr, verified)
        SELECT
            1000 + k.k,
            CONVERT(nvarchar(10), 1000 + k.k),
            CAST(((k.k - 1) % 10) + 1 AS tinyint),
            CASE WHEN k.k % 5 = 0 THEN N''VESSEL_HEATER_TRTR'' ELSE N''HEATER'' END,
            CASE WHEN k.k % 5 = 0 THEN N''VESSEL''             ELSE N''HEATER'' END,
            CASE WHEN k.k % 5 = 0 THEN N''HEATER TREATER''     ELSE N''HEATER'' END,
            N''FIRED'',
            CAST(1 + (k.k % 40) * 0.25 AS decimal(18,4)),
            N''SYN-TAG-'' + CONVERT(nvarchar(10), 1000 + k.k),
            N''SYN-SN-''  + CONVERT(nvarchar(10), 1000 + k.k),
            CASE k.k % 3 WHEN 0 THEN N''SYNTHETIC MFR A'' WHEN 1 THEN N''SYNTHETIC MFR B'' ELSE N''SYNTHETIC MFR C'' END,
            CASE WHEN k.k % 10 = 0 THEN 5 WHEN k.k % 7 = 0 THEN 3 ELSE 0 END
        FROM @k AS k;

        /* Reseed so that equipment_id starts at 1 even after an earlier rolled-back load */
        BEGIN TRY
            DBCC CHECKIDENT (N''dev.stub_equipment'', RESEED, 0) WITH NO_INFOMSGS;
        END TRY
        BEGIN CATCH
            PRINT ''INFO STUB.3 could not reseed the identity (error '' + CAST(ERROR_NUMBER() AS varchar(12)) + ''); equipment_id may not start at 1 after an earlier failed load.'';
        END CATCH;

        BEGIN TRANSACTION;

        INSERT INTO dev.stub_floc
            (functional_location, floc_description, superior_functional_location, floc_class, tech_object_type,
             floc_user_status, profit_center_name, level1_id, level2_id, level3_id, level4_id, level5_id, level6_id,
             golden_version_id, last_changed_at_utc)
        SELECT
            N''SYN-FL-'' + s.code,
            N''SYNTHETIC SLOT '' + s.code,
            N''SYN-FL-AREA-'' + RIGHT(N''00'' + CONVERT(nvarchar(10), s.pc), 2),
            s.floc_class,
            N''PROCESS_UNIT'',
            N''ACTV'',
            p.name,
            N''SYN-ORG'',
            N''SYN-BU-''   + RIGHT(N''00'' + CONVERT(nvarchar(10), s.pc), 2),
            N''SYN-AREA-'' + RIGHT(N''00'' + CONVERT(nvarchar(10), s.pc), 2),
            N''SYN-FAC-''  + s.code,
            N''SYN-SYS-''  + s.code,
            N''SYN-FL-''   + s.code,
            1,
            NULL
        FROM @stage AS s
        JOIN @pc AS p ON p.idx = s.pc
        ORDER BY s.seq;

        INSERT INTO dev.stub_equipment
            (equipment_number, equipment_description, functional_location, equipment_tag_number, equip_class,
             class_type, object_type, manufacturer, model_number, manufacturer_serial_number, fired_unfired,
             heat_duty_mmbtu_hr, heat_duty_source, equipment_user_status, profit_center_name, planner_group,
             heater_population_method, golden_version_id, last_changed_at_utc, baseline_as_of_utc,
             key_fields_verified, last_verified_at_utc)
        SELECT
            N''SYN-EQ-'' + s.code,
            N''SYNTHETIC '' + s.class_type + N'' '' + s.code,
            N''SYN-FL-'' + s.code,
            s.tag,
            s.equip_class,
            s.class_type,
            s.equip_class,
            s.mfr,
            N''SYN-MODEL-'' + CONVERT(nvarchar(5), (s.seq % 5) + 1),
            s.serial,
            s.fired,
            s.duty,
            CASE WHEN s.duty IS NULL THEN N''MISSING'' ELSE N''STATED'' END,
            N''OPER'',
            p.name,
            N''SYN-PG-'' + RIGHT(N''00'' + CONVERT(nvarchar(10), s.pc), 2),
            CASE s.seq % 3 WHEN 0 THEN N''GHGRP'' WHEN 1 THEN N''MANUAL'' ELSE N''BOTH'' END,
            1,
            NULL,
            CAST(N''2000-01-01T00:00:00.000'' AS datetime2(3)),
            s.verified,
            CASE WHEN s.verified > 0 THEN CAST(N''2000-01-02T00:00:00.000'' AS datetime2(3)) ELSE NULL END
        FROM @stage AS s
        JOIN @pc AS p ON p.idx = s.pc
        ORDER BY s.seq;

        INSERT INTO dev.stub_defect (equipment_number, defect_code, note) VALUES
            (N''SYN-EQ-0002'', N''UNFIRED_TREATER'',   N''heater treater marked UNFIRED''),
            (N''SYN-EQ-0008'', N''UNFIRED_TREATER'',   N''heater treater marked UNFIRED''),
            (N''SYN-EQ-0014'', N''UNFIRED_TREATER'',   N''heater treater marked UNFIRED''),
            (N''SYN-EQ-0023'', N''UNFIRED_TREATER'',   N''heater treater marked UNFIRED''),
            (N''SYN-EQ-0003'', N''MISSING_HEAT_DUTY'', N''no heat duty''),
            (N''SYN-EQ-0011'', N''MISSING_HEAT_DUTY'', N''no heat duty''),
            (N''SYN-EQ-0019'', N''MISSING_HEAT_DUTY'', N''no heat duty''),
            (N''SYN-EQ-0026'', N''MISSING_HEAT_DUTY'', N''no heat duty''),
            (N''SYN-EQ-0006'', N''DUPLICATE_SERIAL'',  N''shares SYN-SN-DUP-A with SYN-EQ-0015''),
            (N''SYN-EQ-0015'', N''DUPLICATE_SERIAL'',  N''shares SYN-SN-DUP-A with SYN-EQ-0006''),
            (N''SYN-EQ-0009'', N''DUPLICATE_SERIAL'',  N''shares SYN-SN-DUP-B with SYN-EQ-0029''),
            (N''SYN-EQ-0029'', N''DUPLICATE_SERIAL'',  N''shares SYN-SN-DUP-B with SYN-EQ-0009''),
            (N''SYN-EQ-0007'', N''MISSING_TAG'',       N''no engineering tag''),
            (N''SYN-EQ-0016'', N''MISSING_TAG'',       N''no engineering tag''),
            (N''SYN-EQ-0021'', N''MISSING_TAG'',       N''no engineering tag''),
            (N''SYN-EQ-0030'', N''MISSING_TAG'',       N''no engineering tag''),
            (N''SYN-EQ-0001'', N''CLASS_MISMATCH'',    N''floc class HEATER but equipment class VESSEL''),
            (N''SYN-EQ-0010'', N''CLASS_MISMATCH'',    N''class type BOILER on a HEATER''),
            (N''SYN-EQ-0018'', N''CLASS_MISMATCH'',    N''floc class VESSEL_HEATER_TRTR but equipment class HEATER''),
            (N''SYN-EQ-0025'', N''CLASS_MISMATCH'',    N''floc class BOILER but equipment class HEATER'');

        COMMIT TRANSACTION;

        SET @steps += 1;
        PRINT ''OK  STUB.3 synthetic rows loaded (30 hand-planned + 2500 clean filler heaters, 20 planned defects)'';
    END
    ELSE
    BEGIN
        SET @steps += 1;
        PRINT ''INFO STUB.3 stub tables already hold rows: nothing loaded (run db/dev/drop_stub.sql first to rebuild them)'';
    END
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    SET @steps += 1; SET @failed += 1;
    PRINT ''FAIL STUB.3 load, error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- STUB.4 the planned defects really are in the data ------------------- */
BEGIN TRY
    DECLARE @bad nvarchar(2000);
    DECLARE @chk TABLE (defect_code nvarchar(30) NOT NULL PRIMARY KEY, in_data int NOT NULL);

    INSERT INTO @chk (defect_code, in_data)
    SELECT N''UNFIRED_TREATER'', COUNT(*)
    FROM dev.stub_equipment AS e JOIN dev.stub_floc AS f ON f.functional_location = e.functional_location
    WHERE e.fired_unfired = N''UNFIRED'' AND f.floc_class = N''VESSEL_HEATER_TRTR''
    UNION ALL
    SELECT N''MISSING_HEAT_DUTY'', COUNT(*) FROM dev.stub_equipment WHERE heat_duty_mmbtu_hr IS NULL
    UNION ALL
    SELECT N''MISSING_TAG'', COUNT(*) FROM dev.stub_equipment WHERE equipment_tag_number IS NULL
    UNION ALL
    SELECT N''DUPLICATE_SERIAL'', ISNULL(SUM(d.c), 0)
    FROM (SELECT COUNT(*) AS c FROM dev.stub_equipment GROUP BY manufacturer_serial_number HAVING COUNT(*) > 1) AS d
    UNION ALL
    SELECT N''CLASS_MISMATCH'', COUNT(*)
    FROM dev.stub_equipment AS e JOIN dev.stub_floc AS f ON f.functional_location = e.functional_location
    WHERE NOT (   (f.floc_class = N''HEATER''             AND e.equip_class = N''HEATER'' AND e.class_type = N''HEATER'')
               OR (f.floc_class = N''VESSEL_HEATER_TRTR'' AND e.equip_class = N''VESSEL'' AND e.class_type = N''HEATER TREATER''));

    SELECT @bad = STRING_AGG(c.defect_code + N'': data has '' + CONVERT(nvarchar(12), c.in_data)
                             + N'', dev.stub_defect lists '' + CONVERT(nvarchar(12), ISNULL(l.n, 0)), N''; '')
    FROM @chk AS c
    LEFT JOIN (SELECT defect_code, COUNT(*) AS n FROM dev.stub_defect GROUP BY defect_code) AS l
           ON l.defect_code = c.defect_code
    WHERE c.in_data <> ISNULL(l.n, 0);

    SET @steps += 1;
    IF @bad IS NULL
        PRINT ''OK  STUB.4 planned defects match the data (4 unfired treaters, 4 missing heat duty, 4 duplicate-serial rows, 4 missing tags, 4 class mismatches)'';
    ELSE
    BEGIN
        SET @failed += 1;
        PRINT ''FAIL STUB.4 defect list and data disagree: '' + LEFT(@bad, 1500);
    END
END TRY
BEGIN CATCH
    SET @steps += 1; SET @failed += 1;
    PRINT ''FAIL STUB.4 defect check, error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- STUB.5a gold.vw_equipment_current (contract 01 section 6.1) ---------- */
BEGIN TRY
    IF OBJECT_ID(N''gold.vw_equipment_current'') IS NULL
    BEGIN
        EXEC (N''CREATE VIEW gold.vw_equipment_current
AS
-- ATLAS-STUB: synthetic stand-in over dev.stub_equipment and dev.stub_floc. Replaced by the real view from the data engineer (01 section 6.1); db/dev/drop_stub.sql removes only views that carry this marker.
SELECT
    CAST(e.equipment_id                 AS int)           AS equipment_id,
    CAST(e.equipment_number             AS nvarchar(18))  AS equipment_number,
    CAST(e.equipment_description        AS nvarchar(40))  AS equipment_description,
    CAST(e.functional_location          AS nvarchar(40))  AS functional_location,
    CAST(f.floc_description             AS nvarchar(40))  AS floc_description,
    CAST(f.superior_functional_location AS nvarchar(40))  AS superior_functional_location,
    CAST(e.equipment_tag_number         AS nvarchar(30))  AS equipment_tag_number,
    CAST(e.equip_class                  AS nvarchar(30))  AS equip_class,
    CAST(e.class_type                   AS nvarchar(30))  AS class_type,
    CAST(e.object_type                  AS nvarchar(30))  AS object_type,
    CAST(f.floc_class                   AS nvarchar(30))  AS floc_class,
    CAST(f.tech_object_type             AS nvarchar(30))  AS tech_object_type,
    CAST(e.manufacturer                 AS nvarchar(30))  AS manufacturer,
    CAST(e.model_number                 AS nvarchar(20))  AS model_number,
    CAST(e.manufacturer_serial_number   AS nvarchar(30))  AS manufacturer_serial_number,
    CAST(e.fired_unfired                AS nvarchar(30))  AS fired_unfired,
    CAST(e.heat_duty_mmbtu_hr           AS decimal(18,4)) AS heat_duty_mmbtu_hr,
    CAST(e.heat_duty_source             AS nvarchar(20))  AS heat_duty_source,
    CAST(e.equipment_user_status        AS nvarchar(30))  AS equipment_user_status,
    CAST(f.floc_user_status             AS nvarchar(30))  AS floc_user_status,
    CAST(e.profit_center_name           AS nvarchar(40))  AS profit_center_name,
    CAST(e.planner_group                AS nvarchar(40))  AS planner_group,
    CAST(e.heater_population_method     AS nvarchar(10))  AS heater_population_method,
    CAST(e.golden_version_id            AS int)           AS golden_version_id,
    CAST(e.last_changed_at_utc          AS datetime2(3))  AS last_changed_at_utc,
    CAST(e.baseline_as_of_utc           AS datetime2(3))  AS baseline_as_of_utc
FROM dev.stub_equipment AS e
JOIN dev.stub_floc AS f ON f.functional_location = e.functional_location'');
        PRINT ''OK  STUB.5a created stub view gold.vw_equipment_current'';
    END
    ELSE IF OBJECT_DEFINITION(OBJECT_ID(N''gold.vw_equipment_current'')) LIKE N''%ATLAS-STUB%''
        PRINT ''OK  STUB.5a stub view gold.vw_equipment_current already exists, left in place'';
    ELSE
        PRINT ''INFO STUB.5a gold.vw_equipment_current already exists and is not the stub (the data engineer''''s real object?): left alone'';
    SET @steps += 1;
END TRY
BEGIN CATCH
    SET @steps += 1; SET @failed += 1;
    PRINT ''FAIL STUB.5a gold.vw_equipment_current, error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- STUB.5b gold.vw_equipment_field_current (long form) ------------------ */
BEGIN TRY
    IF OBJECT_ID(N''gold.vw_equipment_field_current'') IS NULL
    BEGIN
        EXEC (N''CREATE VIEW gold.vw_equipment_field_current
AS
-- ATLAS-STUB: synthetic stand-in, one row per heater and EQUIPMENT-entity catalogue field (12 fields).
-- FLOC_CLASS is not listed: it is a field of the functional location (entity FLOC), not of the heater.
-- Numbers are formatted by CONVERT, which never uses a locale (12.5000). baseline_value equals current_value in the stub.
SELECT
    CAST(CONVERT(nvarchar(20), e.equipment_id) + N''''|'''' + v.field_code AS nvarchar(80)) AS equipment_field_key,
    CAST(e.equipment_id AS int)                 AS equipment_id,
    CAST(v.field_code AS nvarchar(64))          AS field_code,
    CAST(v.current_value AS nvarchar(400))      AS current_value,
    CAST(v.current_value AS nvarchar(400))      AS baseline_value,
    CAST(v.unit AS nvarchar(20))                AS unit,
    CAST(CASE WHEN v.field_code = N''''HEAT_DUTY'''' THEN e.heat_duty_source
              WHEN v.current_value IS NULL      THEN N''''MISSING''''
              ELSE N''''STATED'''' END AS nvarchar(20)) AS value_source,
    CAST(NULL AS bigint)                        AS last_request_id,
    CAST(e.last_changed_at_utc AS datetime2(3)) AS last_changed_at_utc
FROM dev.stub_equipment AS e
CROSS APPLY (VALUES
    (N''''MANUFACTURER'''',          CAST(e.manufacturer AS nvarchar(400)),                 CAST(NULL AS nvarchar(20))),
    (N''''MODEL_NUMBER'''',          CAST(e.model_number AS nvarchar(400)),                 CAST(NULL AS nvarchar(20))),
    (N''''SERIAL_NUMBER'''',         CAST(e.manufacturer_serial_number AS nvarchar(400)),   CAST(NULL AS nvarchar(20))),
    (N''''FIRED_UNFIRED'''',         CAST(e.fired_unfired AS nvarchar(400)),                CAST(NULL AS nvarchar(20))),
    (N''''HEAT_DUTY'''',             CONVERT(nvarchar(400), e.heat_duty_mmbtu_hr),          CAST(N''''MMBTU/hr'''' AS nvarchar(20))),
    (N''''EQUIPMENT_TAG_NUMBER'''',  CAST(e.equipment_tag_number AS nvarchar(400)),         CAST(NULL AS nvarchar(20))),
    (N''''EQUIPMENT_DESCRIPTION'''', CAST(e.equipment_description AS nvarchar(400)),        CAST(NULL AS nvarchar(20))),
    (N''''EQUIP_CLASS'''',           CAST(e.equip_class AS nvarchar(400)),                  CAST(NULL AS nvarchar(20))),
    (N''''CLASS_TYPE'''',            CAST(e.class_type AS nvarchar(400)),                   CAST(NULL AS nvarchar(20))),
    (N''''OBJECT_TYPE'''',           CAST(e.object_type AS nvarchar(400)),                  CAST(NULL AS nvarchar(20))),
    (N''''EQUIPMENT_USER_STATUS'''', CAST(e.equipment_user_status AS nvarchar(400)),        CAST(NULL AS nvarchar(20))),
    (N''''FUNCTIONAL_LOCATION'''',   CAST(e.functional_location AS nvarchar(400)),          CAST(NULL AS nvarchar(20)))
) AS v (field_code, current_value, unit)'');
        PRINT ''OK  STUB.5b created stub view gold.vw_equipment_field_current'';
    END
    ELSE IF OBJECT_DEFINITION(OBJECT_ID(N''gold.vw_equipment_field_current'')) LIKE N''%ATLAS-STUB%''
        PRINT ''OK  STUB.5b stub view gold.vw_equipment_field_current already exists, left in place'';
    ELSE
        PRINT ''INFO STUB.5b gold.vw_equipment_field_current already exists and is not the stub (the data engineer''''s real object?): left alone'';
    SET @steps += 1;
END TRY
BEGIN CATCH
    SET @steps += 1; SET @failed += 1;
    PRINT ''FAIL STUB.5b gold.vw_equipment_field_current, error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- STUB.5c gold.vw_floc_current ----------------------------------------- */
BEGIN TRY
