    BEGIN
        EXEC (N''CREATE VIEW gold.vw_floc_current
AS
-- ATLAS-STUB: synthetic stand-in over dev.stub_floc. Column types for this view are not stated in 01 section 6.1; they follow the equipment view (names 40, classes and statuses 30).
SELECT
