    CAST(f.last_changed_at_utc          AS datetime2(3)) AS last_changed_at_utc
FROM dev.stub_floc AS f'');
        PRINT ''OK  STUB.5c created stub view gold.vw_floc_current'';
    END
    ELSE IF OBJECT_DEFINITION(OBJECT_ID(N''gold.vw_floc_current'')) LIKE N''%ATLAS-STUB%''
        PRINT ''OK  STUB.5c stub view gold.vw_floc_current already exists, left in place'';
    ELSE
        PRINT ''INFO STUB.5c gold.vw_floc_current already exists and is not the stub (the data engineer''''s real object?): left alone'';
