/* ---- STUB.5d gold.vw_verification_score ----------------------------------- */
BEGIN TRY
    IF OBJECT_ID(N''gold.vw_verification_score'') IS NULL
    BEGIN
        EXEC (N''CREATE VIEW gold.vw_verification_score
AS
-- ATLAS-STUB: synthetic stand-in. Formula (working assumption for Q-454): verification_pct = key_fields_verified / key_fields_total * 100, key_fields_total = 5. Column types are not stated in 01 section 6.1; chosen here.
SELECT
    CAST(e.equipment_id AS int)                                  AS equipment_id,
    CAST(5 AS int)                                               AS key_fields_total,
    CAST(e.key_fields_verified AS int)                           AS key_fields_verified,
    CAST(e.key_fields_verified * 100.0 / 5 AS decimal(5,2))      AS verification_pct,
    CAST(e.last_verified_at_utc AS datetime2(3))                 AS last_verified_at_utc,
    CAST(e.profit_center_name AS nvarchar(40))                   AS profit_center_name
FROM dev.stub_equipment AS e'');
        PRINT ''OK  STUB.5d created stub view gold.vw_verification_score'';
    END
    ELSE IF OBJECT_DEFINITION(OBJECT_ID(N''gold.vw_verification_score'')) LIKE N''%ATLAS-STUB%''
        PRINT ''OK  STUB.5d stub view gold.vw_verification_score already exists, left in place'';
    ELSE
        PRINT ''INFO STUB.5d gold.vw_verification_score already exists and is not the stub (the data engineer''''s real object?): left alone'';
    SET @steps += 1;
END TRY
BEGIN CATCH
    SET @steps += 1; SET @failed += 1;
    PRINT ''FAIL STUB.5d gold.vw_verification_score, error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- STUB.5e gold.vw_verification_by_business_unit ------------------------ */
BEGIN TRY
    IF OBJECT_ID(N''gold.vw_verification_by_business_unit'') IS NULL
    BEGIN
        EXEC (N''CREATE VIEW gold.vw_verification_by_business_unit
AS
-- ATLAS-STUB: synthetic stand-in, one row per profit centre (business unit). Same formula as gold.vw_verification_score; a heater is fully verified when key_fields_verified = 5. Column types are not stated in 01 section 6.1; chosen here.
SELECT
    CAST(e.profit_center_name AS nvarchar(40))                                                  AS profit_center_name,
    CAST(COUNT(*) AS int)                                                                       AS heaters,
    CAST(AVG(e.key_fields_verified * 100.0 / 5) AS decimal(5,2))                                AS avg_verification_pct,
    CAST(SUM(CASE WHEN e.key_fields_verified = 5 THEN 1 ELSE 0 END) AS int)                     AS heaters_fully_verified,
    CAST(SUM(CASE WHEN e.key_fields_verified = 5 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS decimal(5,2)) AS pct_heaters_fully_verified
FROM dev.stub_equipment AS e
GROUP BY e.profit_center_name'');
        PRINT ''OK  STUB.5e created stub view gold.vw_verification_by_business_unit'';
    END
    ELSE IF OBJECT_DEFINITION(OBJECT_ID(N''gold.vw_verification_by_business_unit'')) LIKE N''%ATLAS-STUB%''
        PRINT ''OK  STUB.5e stub view gold.vw_verification_by_business_unit already exists, left in place'';
    ELSE
        PRINT ''INFO STUB.5e gold.vw_verification_by_business_unit already exists and is not the stub (the data engineer''''s real object?): left alone'';
    SET @steps += 1;
END TRY
BEGIN CATCH
    SET @steps += 1; SET @failed += 1;
    PRINT ''FAIL STUB.5e gold.vw_verification_by_business_unit, error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- STUB.6 row counts (information only) --------------------------------- */
BEGIN TRY
    SELECT @n = COUNT(*) FROM dev.stub_floc;
    PRINT ''INFO STUB.6 dev.stub_floc rows: '' + CAST(@n AS varchar(12)) + '' (expected 2530 on a fresh load)'';
    SELECT @n = COUNT(*) FROM dev.stub_equipment;
    PRINT ''INFO STUB.6 dev.stub_equipment rows: '' + CAST(@n AS varchar(12)) + '' (expected 2530 on a fresh load)'';
    SELECT @n = COUNT(*) FROM dev.stub_defect;
    PRINT ''INFO STUB.6 dev.stub_defect rows: '' + CAST(@n AS varchar(12)) + '' (expected 20 on a fresh load)'';
    EXEC sp_executesql N''SELECT @n = COUNT(*) FROM gold.vw_equipment_current'', N''@n int OUTPUT'', @n = @n OUTPUT;
    PRINT ''INFO STUB.6 gold.vw_equipment_current rows: '' + CAST(@n AS varchar(12));
    EXEC sp_executesql N''SELECT @n = COUNT(*) FROM gold.vw_equipment_field_current'', N''@n int OUTPUT'', @n = @n OUTPUT;
    PRINT ''INFO STUB.6 gold.vw_equipment_field_current rows: '' + CAST(@n AS varchar(12)) + '' (12 fields per heater)'';
